// Shelly 3EM-63 Gen3 (Dreiphasen-Profil) -> aufbereitete Werte
// em:0     = Momentanwerte (W, A, V, PF) je Phase + Summe
// emdata:0 = Energiezaehler (Wh), Summe und je Phase
const now = Date.now();
let s = flow.get('wpShelly') || {};

if (msg.topic === 'check') {                       // Ueberwachung (Inject jede Minute)
    if (!s.tP || now - s.tP > 120000) {
        node.status({ fill: 'red', shape: 'ring', text: 'keine Daten seit > 2 min' });
    }
    return null;
}

const comp = String(msg.topic).split('/').pop();   // "em:0" oder "emdata:0"
const p = msg.payload;
if (typeof p !== 'object' || p === null) return null;
const r1 = v => (typeof v === 'number') ? Math.round(v * 10) / 10 : null;
const r3 = v => (typeof v === 'number') ? Math.round(v * 1000) / 1000 : null;

if (comp === 'em:0') {
    s.p   = r1(p.total_act_power);                // W Wirkleistung gesamt
    s.s   = r1(p.total_aprt_power);               // VA Scheinleistung gesamt
    s.i   = r3(p.total_current);                  // A Summe der Phasenstroeme
    s.pf  = (p.total_aprt_power > 1) ? Math.round(p.total_act_power / p.total_aprt_power * 100) / 100 : null;
    s.L1  = { p: r1(p.a_act_power), i: r3(p.a_current), u: r1(p.a_voltage), pf: p.a_pf };
    s.L2  = { p: r1(p.b_act_power), i: r3(p.b_current), u: r1(p.b_voltage), pf: p.b_pf };
    s.L3  = { p: r1(p.c_act_power), i: r3(p.c_current), u: r1(p.c_voltage), pf: p.c_pf };
    s.tP  = now;
} else if (comp === 'emdata:0') {
    if (typeof p.total_act !== 'number') return null;
    s.eTot = Math.round(p.total_act) / 1000;       // kWh Zaehlerstand (Bezug)
    const day = new Date().toLocaleDateString('de-DE');
    if (s.day !== day || typeof s.eDay0 !== 'number') { s.day = day; s.eDay0 = s.eTot; }
    s.eHeute = Math.round((s.eTot - s.eDay0) * 1000) / 1000;   // kWh seit Mitternacht (bzw. seit Node-RED-Start)
    s.tE = now;
} else {
    return null;
}
flow.set('wpShelly', s);

node.status({ fill: 'green', shape: 'dot',
    text: `${s.p ?? '-'} W · ${s.i ?? '-'} A · heute ${s.eHeute ?? '-'} kWh` });

msg.topic = 'wp/strom';
msg.payload = {
    p: s.p, s: s.s, i: s.i, pf: s.pf,
    L1: s.L1, L2: s.L2, L3: s.L3,
    eTot: s.eTot, eHeute: s.eHeute,
    zeit: new Date(now).toISOString()
};
return msg;

const on = String(msg.payload) === 'true';
node.status(on ? { fill: 'green', shape: 'dot', text: 'online' } : { fill: 'red', shape: 'ring', text: 'offline' });
return msg;
